-- Baseline do schema Supabase (gerado de src/db/PostgresDB.ts)
-- Idempotente: CREATE IF NOT EXISTS / ADD COLUMN IF NOT EXISTS

CREATE TABLE IF NOT EXISTS usuarios ( id SERIAL PRIMARY KEY, nome VARCHAR(255) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, senha_hash VARCHAR(255) NOT NULL, perfil VARCHAR(50) NOT NULL, ativo BOOLEAN DEFAULT true, criado_em TIMESTAMPTZ DEFAULT NOW(), tenant_id VARCHAR(50), foto_url TEXT );
CREATE TABLE IF NOT EXISTS moradores ( id SERIAL PRIMARY KEY, nome_completo VARCHAR(255) NOT NULL, cpf VARCHAR(20) NOT NULL, telefone VARCHAR(30), whatsapp VARCHAR(30), telegram VARCHAR(100), bloco VARCHAR(10), apartamento VARCHAR(10), vinculo VARCHAR(20) NOT NULL, foto_url TEXT, numero_vaga VARCHAR(20), ativo BOOLEAN DEFAULT true, criado_em DATE DEFAULT CURRENT_DATE, tenant_id VARCHAR(50) );
CREATE TABLE IF NOT EXISTS veiculos ( id SERIAL PRIMARY KEY, placa VARCHAR(20) NOT NULL, modelo VARCHAR(100), cor VARCHAR(50), vaga VARCHAR(20), morador_id INTEGER REFERENCES moradores(id) ON DELETE SET NULL, tipo_vinculo VARCHAR(20) NOT NULL, titulo VARCHAR(255), criado_em DATE DEFAULT CURRENT_DATE, tenant_id VARCHAR(50) );
CREATE TABLE IF NOT EXISTS visitantes ( id SERIAL PRIMARY KEY, nome VARCHAR(255) NOT NULL, documento VARCHAR(30), tipo_documento VARCHAR(20), telefone VARCHAR(30), foto_url TEXT, placa_veiculo VARCHAR(20), vaga VARCHAR(20), bloco VARCHAR(10), apartamento VARCHAR(10), morador_visitado_id INTEGER REFERENCES moradores(id) ON DELETE SET NULL, agendado_para DATE, presente BOOLEAN DEFAULT false, criado_em DATE DEFAULT CURRENT_DATE, nome_visitante VARCHAR(255) NOT NULL, documento_visitante VARCHAR(30), data_prevista DATE, observacao TEXT, tenant_id VARCHAR(50) );
CREATE TABLE IF NOT EXISTS acessos ( id SERIAL PRIMARY KEY, tipo_pessoa VARCHAR(20) NOT NULL, pessoa_id INTEGER NOT NULL, nome VARCHAR(255) NOT NULL, sentido VARCHAR(10) NOT NULL, placa_veiculo VARCHAR(20), vaga VARCHAR(20), observacao TEXT, registrado_em TIMESTAMPTZ DEFAULT NOW(), tenant_id VARCHAR(50) );
CREATE TABLE IF NOT EXISTS encomendas ( id SERIAL PRIMARY KEY, morador_id INTEGER REFERENCES moradores(id) ON DELETE SET NULL, morador_nome VARCHAR(255) NOT NULL, morador_unidade VARCHAR(50), morador_telefone VARCHAR(30), morador_whatsapp VARCHAR(30), morador_telegram VARCHAR(100), codigo_rastreio VARCHAR(100), transportadora VARCHAR(100), tipo_volume VARCHAR(50), local_armazenamento VARCHAR(100), observacoes TEXT, codigo_retirada VARCHAR(20), status VARCHAR(20) NOT NULL, recebido_em TIMESTAMPTZ, recebido_por VARCHAR(255), retirado_em TIMESTAMPTZ, retirado_por VARCHAR(255), notificacao_enviada_whatsapp BOOLEAN DEFAULT false, notificacao_enviada_telegram BOOLEAN DEFAULT false, mensagem_aviso TEXT, tenant_id VARCHAR(50) );
CREATE TABLE IF NOT EXISTS prestadores ( id SERIAL PRIMARY KEY, nome VARCHAR(255) NOT NULL, documento VARCHAR(30) NOT NULL, tipo_documento VARCHAR(20) NOT NULL, empresa VARCHAR(255), funcao VARCHAR(255) NOT NULL, telefone VARCHAR(30), foto_url TEXT, placa_veiculo VARCHAR(20), cracha_numero VARCHAR(50), tipo_vinculo VARCHAR(20) NOT NULL, bloco VARCHAR(10), apartamento VARCHAR(10), morador_autorizador_id INTEGER REFERENCES moradores(id) ON DELETE SET NULL, morador_autorizador_nome VARCHAR(255), data_inicio DATE NOT NULL, data_fim DATE, horario_permitido VARCHAR(100), observacao TEXT, presente BOOLEAN DEFAULT false, ativo BOOLEAN DEFAULT true, criado_em TIMESTAMPTZ DEFAULT NOW(), tenant_id VARCHAR(50) );
CREATE TABLE IF NOT EXISTS ocorrencias ( id SERIAL PRIMARY KEY, titulo VARCHAR(255) NOT NULL, categoria VARCHAR(50) NOT NULL, gravidade VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL, bloco VARCHAR(10), apartamento VARCHAR(10), morador_envolvido VARCHAR(255), descricao TEXT NOT NULL, acao_tomada TEXT, registrado_por VARCHAR(255) NOT NULL, data_hora TIMESTAMPTZ DEFAULT NOW(), resolvido_em TIMESTAMPTZ, tenant_id VARCHAR(50) );
CREATE TABLE IF NOT EXISTS restricoes_acesso ( id SERIAL PRIMARY KEY, tipo_identificador VARCHAR(20) NOT NULL, valor_identificador VARCHAR(100) NOT NULL, nome_pessoa VARCHAR(255), motivo TEXT NOT NULL, instrucao_portaria TEXT NOT NULL, bloqueio_total BOOLEAN DEFAULT true, ativo BOOLEAN DEFAULT true, criado_por VARCHAR(255), criado_em TIMESTAMPTZ DEFAULT NOW(), tenant_id VARCHAR(50) );
CREATE TABLE IF NOT EXISTS reservas ( id SERIAL PRIMARY KEY, espaco VARCHAR(50) NOT NULL, espaco_nome VARCHAR(255) NOT NULL, data_reserva DATE NOT NULL, periodo VARCHAR(20) NOT NULL, morador_id INTEGER REFERENCES moradores(id) ON DELETE SET NULL, morador_nome VARCHAR(255) NOT NULL, bloco VARCHAR(10), apartamento VARCHAR(10), status VARCHAR(20) NOT NULL, convidados_estimados INTEGER, observacoes TEXT, solicitado_em TIMESTAMPTZ DEFAULT NOW(), aprovado_em TIMESTAMPTZ, aprovado_por VARCHAR(255), tenant_id VARCHAR(50) );
CREATE TABLE IF NOT EXISTS comunicados ( id SERIAL PRIMARY KEY, titulo VARCHAR(255) NOT NULL, categoria VARCHAR(50) NOT NULL, conteudo TEXT NOT NULL, importante BOOLEAN DEFAULT false, publicado_por VARCHAR(255) NOT NULL, data_publicacao TIMESTAMPTZ DEFAULT NOW(), ativo BOOLEAN DEFAULT true, tenant_id VARCHAR(50) );
CREATE TABLE IF NOT EXISTS notificacoes_morador ( id SERIAL PRIMARY KEY, morador_id INTEGER REFERENCES moradores(id) ON DELETE SET NULL, tipo VARCHAR(50) NOT NULL, titulo VARCHAR(255) NOT NULL, mensagem TEXT NOT NULL, canal VARCHAR(20) NOT NULL, enviado_em TIMESTAMPTZ DEFAULT NOW(), lida BOOLEAN DEFAULT false, dados_adicionais JSONB, tenant_id VARCHAR(50) );
CREATE TABLE IF NOT EXISTS preautorizacoes_visitante ( id SERIAL PRIMARY KEY, morador_id INTEGER REFERENCES moradores(id) ON DELETE SET NULL, morador_nome VARCHAR(255) NOT NULL, bloco VARCHAR(10), apartamento VARCHAR(10), nome_visitante VARCHAR(255) NOT NULL, documento_visitante VARCHAR(30), placa_veiculo VARCHAR(20), data_prevista DATE NOT NULL, observacao TEXT, codigo_acesso_qr VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL, criado_em TIMESTAMPTZ DEFAULT NOW(), tenant_id VARCHAR(50) );
CREATE TABLE IF NOT EXISTS leads ( id SERIAL PRIMARY KEY, nome VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL, telefone VARCHAR(30), condominio_nome VARCHAR(255), numero_unidades INTEGER, sistema_atual VARCHAR(255), status VARCHAR(20) NOT NULL, origem VARCHAR(100), observacao TEXT, criado_em TIMESTAMPTZ DEFAULT NOW(), atualizado_em TIMESTAMPTZ DEFAULT NOW(), tenant_id VARCHAR(50) );

CREATE INDEX IF NOT EXISTS idx_usuarios_email ON usuarios(email);
CREATE INDEX IF NOT EXISTS idx_moradores_cpf ON moradores(cpf);
CREATE INDEX IF NOT EXISTS idx_veiculos_placa ON veiculos(placa);
CREATE INDEX IF NOT EXISTS idx_visitantes_morador ON visitantes(morador_visitado_id);
CREATE INDEX IF NOT EXISTS idx_acessos_registrado ON acessos(registrado_em);
CREATE INDEX IF NOT EXISTS idx_encomendas_morador ON encomendas(morador_id);
CREATE INDEX IF NOT EXISTS idx_encomendas_codigo ON encomendas(codigo_retirada);
CREATE INDEX IF NOT EXISTS idx_prestadores_morador ON prestadores(morador_autorizador_id);
CREATE INDEX IF NOT EXISTS idx_reservas_data ON reservas(data_reserva);
CREATE INDEX IF NOT EXISTS idx_notificacoes_morador ON notificacoes_morador(morador_id);

-- Drift corrigido em 2026-11-08: coluna ausente no banco existente
ALTER TABLE usuarios ADD COLUMN IF NOT EXISTS foto_url TEXT;
